export type Actor = 'user' | 'assistant' | 'system'

export interface ConversationMessage {
  /** Stable id, generated by the conversation layer. */
  id: string
  actor: Actor
  /** Rendered text body. For vocal-only turns this is still stored. */
  text: string
  /** ISO timestamp of creation. */
  createdAt: string
  /** Optional linked activity id. */
  activityId?: string
}

export interface PersistedConversation {
  /** Conversation id (stable across refreshes within one thread). */
  id: string
  /** ISO timestamp when the thread started. */
  createdAt: string
  messages: ConversationMessage[]
}

export interface ConversationState {
  /** Conversation id, stable across refreshes. */
  id: string
  /** ISO timestamp when the thread started. */
  createdAt: string
  messages: ConversationMessage[]
  /** Id of the newest message. */
  lastId: string | null
  count: number
}

export interface ConversationEvent {
  type: 'added' | 'cleared'
  message?: ConversationMessage
}
